fn EpicHuntAndPokePlan::is_end(self, version, _rnd, player, data, team_plan, _debug) -> bool
  // self / _rnd / _debug 는 본문에서 단 한 번도 읽히지 않는다.

  // ── L164  team_plan.take_active(JungleType::Morgard)  (team_plan.rs:243 → objective_target@231)
  if team_plan.objective_tag(0x41f) != 0 /*MainObjective::Morgard*/ { return true }   // None(255)·다른 목표는 전부 종료

  // ── L169
  let camp: (u64,u64) = MapDef::camp_pos(data.context.map, JungleType::Morgard /*4*/, player.info.team == 0)

  // ── L172  team_plan.take_setup_like(JungleType::Morgard)  (team_plan.rs:257-258)
  //   IR 은 objective 태그를 재로드해 ==0 인지 본 뒤 phase 를 검사한다.
  let setup_like = (team_plan.objective_tag(0x41f) == 0)
                && (team_plan.objective.Morgard.phase(0x420) == ObjectPhase::Setup /*1*/)

  if setup_like {
      // ── L174
      if TeamPlan::v24_objective_setup_should_release_to_passive(team_plan, version, player, data, JungleType::Morgard /*4*/) {
          return true                                  // 세팅 단계를 수동 태세로 놓아야 하면 종료
      }

      // ── L179  캠프 칸이 우리 팀 시야에 잡히는가 (AbstractGame vtable +0x100 → bool)
      if !game.vt[0x100](player.info.team, camp.0 / 32000, camp.1 / 32000) {
          goto L193                                    // 안 보이면 거리 게이트를 건너뛰고 리스폰 게이트로
      }

      // ── L180~181  적 팀(1 - player.info.team) 챔피언 중 캠프에 가장 가까운 하나
      //   원본  = data.cache.player_champion[1-team] (5칸 Option<&Entity>, 인덱스는 2로 bounds check)
      //   filter(L180) = Blackboard[1-team].is_recent_visible(&dyn AbstractGame, player, entity)
      //   key   (L181) = distance_sq((e.x@0x660, e.y@0x668), camp)   // game-core/src/utils.rs:6-9, abs_diff 제곱합
      let nearest = iter_champions(1 - player.info.team).filter(..).min_by_key(..)

      // ── L183~184
      match nearest {
          None    => return true,                      // 최근 목격된 적 챔피언이 하나도 없으면 종료
          Some(e) => if distance_sq((e.x, e.y), camp) > 22500000000 /*150000^2*/ { return true }
      }
  }

  // ── L193  (setup_like 아님 / 캠프 시야 없음 / 적이 충분히 가까움 → 여기로 합류)
  let moba = game.vt[0x40]().as_moba().unwrap()        // Moba 모드가 아니면 unwrap_failed 패닉
  let epic = moba.jungle_runner.epic.live_list.get(0)  // len(0x1a8)==0 이면 None
                 .and_then(|id| game.vt[0x1f0](*id))   // closure$2 @L193 — 엔티티 조회, null 이면 None

  // ── L194
  if epic.is_some() { return false }                   // 에픽이 필드에 살아있으면 플랜 유지
  return moba.jungle_runner.epic.next_respawn_tick(0x1b0)
             .saturating_sub(game.vt[0x28]() /*현재 tick*/)
         > data.context.setting.tick_per_second * 15   // 리스폰까지 15초 넘게 남았으면 종료

── true 를 내는 5가지 경로(요약)
  1) objective 가 Morgard 가 아님 (L164)
  2) v24_objective_setup_should_release_to_passive == true (L174)
  3) Setup 페이즈 + 캠프 시야 있음인데 최근 목격 적 챔피언이 0명 (L183)
  4) 그 최근접 적이 캠프에서 150000 초과로 떨어짐 (L184)
  5) 에픽이 필드에 없고 리스폰까지 15초 초과로 남음 (L194)
── false 는 사실상 하나: 에픽이 필드에 존재(L194), 또는 리스폰이 15초 이내
